import os
import torch


class Config:
    """
    Configuration class for Bird Species Classification.
    Defines paths, hyperparameters, and model settings for the heterogeneous ensemble.
    """

    # ==========================================
    # General Settings
    # ==========================================
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # ==========================================
    # Paths
    # ==========================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the metadata script
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Source data
    SPECTROGRAM_DIR = os.path.join(INPUT_ROOT, "supplemental_data", "spectrograms")

    # Output directories
    WORKING_DIR = "./working/idea_12"
    CACHE_DIR = os.path.join(WORKING_DIR, "cache")
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "checkpoints")
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Parameters
    # ==========================================
    NUM_CLASSES = 19
    NUM_FOLDS = 5

    # Input dimensions
    IMAGE_SIZE = 224  # Resize to 224x224
    INPUT_CHANNELS = 3  # Replicate single channel to 3 for pretrained models

    # DataLoader settings
    BATCH_SIZE = 32
    NUM_WORKERS = 4
    PIN_MEMORY = True if torch.cuda.is_available() else False

    # ==========================================
    # Model Architecture
    # ==========================================
    # Heterogeneous Ensemble Backbones
    MODELS = ["resnet18", "efficientnet_b0", "densenet121"]
    PRETRAINED = True

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    EPOCHS = 100  # Max epochs, controlled by early stopping
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2  # For AdamW

    # Early Stopping
    PATIENCE = 20

    # Scheduler (Cosine Annealing)
    T_MAX = EPOCHS
    ETA_MIN = 1e-6

    # Regularization
    USE_MIXUP = True
    MIXUP_ALPHA = 0.4

    # ==========================================
    # Augmentation Settings
    # ==========================================
    # Photometric
    BRIGHTNESS_JITTER = 0.2
    CONTRAST_JITTER = 0.2

    # Geometric
    # Note: Horizontal Flip is strictly disabled for spectrograms
    TIME_SHIFT_LIMIT = 0.1  # Shift up to 10% of time dimension

    # ==========================================
    # Debugging / Development
    # ==========================================
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SAMPLE_SIZE = 32  # Number of samples to use in debug mode

    @classmethod
    def setup(cls):
        """
        Initialize the working directories.
        Should be called at the start of the execution.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.CHECKPOINT_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
